package com.obra.studio.ui

import android.os.Bundle
import android.content.Intent
import android.widget.*
import androidx.activity.OnBackPressedCallback
import androidx.activity.result.contract.ActivityResultContracts
import com.obra.studio.data.*
import java.time.LocalDate

class FormActivity:BaseActivity() {
    private var mode="add";private var workId=0L;private var step=1
    private var draft=CommissionDraft();private var baseline=CommissionDraft()
    private val fields=linkedMapOf<String,EditText>()
    private var amount="";private var paidOn=LocalDate.now().toString();private var method="GCash";private var paymentNote="";private var stage="";private var finished=LocalDate.now().toString();private var completing=false
    private val picker=registerForActivityResult(ActivityResultContracts.OpenMultipleDocuments()) { uris->uris.take((6-draft.images.size).coerceAtLeast(0)).forEach { uri->try { contentResolver.takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION) } catch (_:SecurityException){};draft.images.add(uri.toString()) };render() }
    override fun onCreate(state:Bundle?) { super.onCreate(state);mode=intent.getStringExtra("mode")?:"add";workId=intent.getLongExtra("commissionId",0)
        val c=Studio.work(workId)
        if(mode!="add" && c==null){reset("Record unavailable");empty("Record unavailable","Return to the previous screen.");return}
        if(c!=null) {draft=CommissionDraft(platform=c.platform,username=c.username,title=c.title,type=c.type,genre=c.genre,brief=c.brief,total=java.math.BigDecimal(c.totalMinor).movePointLeft(2).toPlainString(),commissionOn=c.commissionOn,dueOn=c.dueOn,plannedStart=c.plannedStart);stage=c.stage}
        baseline=draft.copy(images=ArrayList(draft.images))
        if(state!=null){ @Suppress("DEPRECATION") val saved=state.getSerializable("draft") as? CommissionDraft;if(saved!=null)draft=saved;step=state.getInt("step",1);amount=state.getString("amount")?:"";paidOn=state.getString("paidOn")?:paidOn;method=state.getString("method")?:method;paymentNote=state.getString("note")?:"";stage=state.getString("stage")?:stage;finished=state.getString("finished")?:finished;completing=state.getBoolean("completing") }
        onBackPressedDispatcher.addCallback(this,object:OnBackPressedCallback(true){override fun handleOnBackPressed(){capture();if((mode=="add"||mode=="edit")&&step>1){step--;render()}else if(completing){completing=false;render()}else leave()} });render()
    }
    override fun onSaveInstanceState(out:Bundle){capture();super.onSaveInstanceState(out);out.putSerializable("draft",draft);out.putInt("step",step);out.putString("amount",amount);out.putString("paidOn",paidOn);out.putString("method",method);out.putString("note",paymentNote);out.putString("stage",stage);out.putString("finished",finished);out.putBoolean("completing",completing)}
    private fun leave(){val dirty=if(mode=="add"||mode=="edit")draft!=baseline else amount.isNotBlank()||paymentNote.isNotBlank()||stage!=Studio.work(workId)?.stage;if(dirty)confirm("Discard changes?","Your unsaved input will be discarded."){finish()}else finish()}
    private fun field(key:String,label:String,value:String,multi:Boolean=false){fields[key]=input(label,value,multiline=multi);if(key in listOf("total","initialAmount","amount"))fields[key]!!.inputType=android.text.InputType.TYPE_CLASS_NUMBER or android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL}
    private fun capture(){fields.forEach { (k,e)->val v=e.text.toString();when(k){"username"->draft.username=v;"name"->draft.displayName=v;"title"->draft.title=v;"genre"->draft.genre=v;"tags"->draft.tags=v;"brief"->draft.brief=v;"total"->draft.total=v;"initialAmount"->draft.initialAmount=v;"initialNote"->draft.initialNote=v;"amount"->amount=v;"note"->paymentNote=v} }}
    private fun render(){fields.clear();reset(when(mode){"edit"->"Edit commission";"payment"->"Record payment";"payments"->"Payment history";"progress"->if(completing)"Review completion" else "Update progress";else->"New commission"})
        if(mode=="payments"){payments();return};if(mode=="payment"){payment();return};if(mode=="progress"){progress();return}
        note("Step $step of 4");button("Close form") { capture();leave() }
        when(step){1->{section("Client details");note("Who are we creating for?");choose("Contact platform *",listOf("X","Discord"),draft.platform){draft.platform=it};field("username","Client username *",draft.username);field("name","Display name · Optional",draft.displayName)}
            2->{section("Artwork brief");note("Give the request a little shape.");field("title","Project title *",draft.title);choose("Commission type *",listOf("Full body","Half body","Chibi","Portrait","Full illustration","Character sheet","Icon"),draft.type){draft.type=it};field("genre","Primary genre · Optional",draft.genre);field("tags","Style tags · Optional",draft.tags);field("brief","Pose & details",draft.brief,true);section("Reference images");note("${draft.images.size} of 6 images");draft.images.toList().forEachIndexed { index,uri->button("View reference ${index+1}"){capture();startActivity(Intent(this,ViewerActivity::class.java).putStringArrayListExtra("images",draft.images).putExtra("index",index))};button("Remove reference ${index+1}"){capture();draft.images.remove(uri);render()} };button("+ Add image"){capture();picker.launch(arrayOf("image/*"))}.isEnabled=draft.images.size<6}
            3->{section("Price & dates");note("A clear quote. A little breathing room.");if(mode=="add"){val base=when(draft.type){"Full body"->2500;"Half body"->1500;"Chibi"->1200;"Full illustration"->4500;"Character sheet"->3200;"Icon"->500;else->1800};card(sage){text("Suggested quote: ${Studio.money((base+if(draft.background)500 else 0)*100L)}",17,true,it)};val cb=CheckBox(this);cb.text="Detailed background (+ ₱500)";cb.isChecked=draft.background;body.addView(cb);cb.setOnClickListener{capture();draft.background=cb.isChecked;render()}}
                field("total","Agreed total (PHP) *",draft.total)
                if(mode=="edit")note("Already received: ${Studio.money(Studio.received(workId))}. Existing receipts remain unchanged.")
                dateField("Commission date",draft.commissionOn){capture();draft.commissionOn=it;render()};dateField("Due date",draft.dueOn){capture();draft.dueOn=it;render()};dateField("Planned start · Optional",draft.plannedStart){capture();draft.plannedStart=it;render()};if(draft.plannedStart.isNotBlank())button("Clear planned start"){capture();draft.plannedStart="";render()}
                if(mode=="add"){val cb=CheckBox(this);cb.text="Record initial payment";cb.typeface=heading;cb.isChecked=draft.initialEnabled;body.addView(cb);cb.setOnClickListener{capture();draft.initialEnabled=cb.isChecked;render()};if(draft.initialEnabled){field("initialAmount","Amount received (PHP) *",draft.initialAmount);dateField("Date received",draft.initialDate){capture();draft.initialDate=it;render()};choose("Payment method",methods,draft.initialMethod){draft.initialMethod=it};field("initialNote","Payment note · Optional",draft.initialNote)}}}
            4->{section(if(mode=="edit")"Review changes" else "One last look");if(mode=="edit"){val changes=mutableListOf<String>();if(draft.username!=baseline.username)changes.add("Username: ${baseline.username} → ${draft.username}");if(draft.title!=baseline.title)changes.add("Title: ${baseline.title} → ${draft.title}");if(draft.total!=baseline.total)changes.add("Price: ${baseline.total} → ${draft.total}");if(draft.dueOn!=baseline.dueOn)changes.add("Due: ${baseline.dueOn} → ${draft.dueOn}");text(changes.joinToString("\n").ifEmpty { if(draft==baseline)"No changes to save." else "Review the updated details below." })}
                review("Client","${draft.username} · ${draft.platform}\n${draft.displayName}",1);review("Artwork","${draft.title}\n${draft.type} · ${draft.genre}\n${draft.tags}\n${draft.brief}\n${draft.images.size} references",2);review("Schedule","Commission: ${draft.commissionOn}\nPlanned start: ${draft.plannedStart.ifEmpty { "Not set" }}\nDue: ${draft.dueOn}",3);review("Price & payment","Agreed total: ₱${draft.total}\nInitial payment: ${if(draft.initialEnabled)"₱${draft.initialAmount}" else "None"}",3)} }
        val label=when(step){1->"Next: Artwork";2->"Next: Price & dates";3->if(mode=="edit")"Review changes" else "Review commission";else->if(mode=="edit")"Save changes" else "Save commission"}
        button(label,footer,true){capture();val issue=validate(step);if(issue!=null)error(issue)else if(step<4){step++;render();scroll.scrollTo(0,0)}else pending()}.isEnabled=!(step==4&&mode=="edit"&&draft==baseline)
    }
    private fun review(label:String,value:String,target:Int){card{ text(label,20,true,it);text(value,15,false,it);button("Edit",it){step=target;render()} }}
    private fun validate(until:Int):String? {
        if(draft.username.isBlank())return "Enter the client's username."
        if(until>=2&&draft.title.isBlank())return "Enter the project title."
        if(until>=3){val total=Validation.minor(draft.total)?:return "Enter a positive price with at most two decimal places (maximum PHP 1 billion).";Validation.schedule(draft,Studio.work(workId))?.let{return it}
            if(mode=="edit"){if(total<Studio.received(workId))return "Price cannot be below payments already received.";if(Studio.repository.payments().any{it.commissionId==workId&&it.receivedOn<draft.commissionOn})return "Commission date cannot be after an existing receipt."}
            if(draft.initialEnabled){val initial=Validation.minor(draft.initialAmount)?:return "Enter a valid initial payment.";if(initial>total)return "Initial payment exceeds the agreed price.";val date=Validation.date(draft.initialDate)?:return "Choose a valid received date.";if(date<Validation.date(draft.commissionOn)||date>LocalDate.now())return "Received date must be between commission date and today."}}
        return null
    }
    private val methods=listOf("GCash","Bank transfer","PayPal","Cash","Other")
    private fun payment(){val c=Studio.work(workId)!!;card(sage){text(c.title,20,true,it);text("Remaining: ${Studio.money(Studio.balance(c))}",20,false,it)};field("amount","Amount received (PHP) *",amount);dateField("Received date",paidOn){capture();paidOn=it;render()};choose("Method",methods,method){method=it};field("note","Note · Optional",paymentNote,true);button("Save payment",footer,true){capture();val n=Validation.minor(amount);val d=Validation.date(paidOn);when{n==null->error("Enter a positive amount with at most two decimal places.");n>Studio.balance(c)->error("Payment cannot exceed the remaining balance.");d==null||d<Validation.date(c.commissionOn)||d>LocalDate.now()->error("Received date must be between commission date and today.");else->pending()}} }
    private fun payments(){val c=Studio.work(workId)!!;section(c.title);card(sage){text("Received ${Studio.money(Studio.received(workId))}\nRemaining ${Studio.money(Studio.balance(c))}",23,false,it)};val ps=Studio.repository.payments().filter{it.commissionId==workId};if(ps.isEmpty())empty("No payments yet","Record money only after it has been received.");ps.sortedByDescending{it.receivedOn}.forEach { p->card{text(Studio.money(p.amountMinor),25,false,it);text("${p.receivedOn}\n${p.method}\n${p.note}",15,false,it)} };button("Record payment",primary=true){form("payment",workId)}.isEnabled=Studio.balance(c)>0;button("Back to commission"){finish()} }
    private fun progress(){val c=Studio.work(workId)!!;section(c.title);if(completing){note("Finishing the artwork keeps its receipts and checklist unchanged.");dateField("Actual finish date",finished){finished=it;render()};text("Remaining balance: ${Studio.money(Studio.balance(c))}");button("Mark completed",footer,true){val date=Validation.date(finished);val start=Validation.date(c.startedOn);if(date==null||start==null||date<start||date>LocalDate.now())error("Finish date must be between the actual start and today.")else pending()};button("Keep working"){completing=false;render()}}
        else {choose("Creative stage",listOf("Sketch","Lineart","Colors","Finished"),stage){stage=it};note("Work progress and payment progress are independent.");button("Continue",footer,true){if(stage=="Finished"){completing=true;render()}else if(stage==c.stage)error("Choose a different stage to update progress.")else pending()}} }
}
